/**
 * Physics Fields — forces that give physics meaning beyond "things fall".
 *
 * All of these are read from the artboard every frame, so changing the data
 * (a tag, a buoyancy value, an orbit radius) changes the motion live.
 *
 * Attractor (on any object; it follows that object, so a draggable magnet works):
 *   obj.physicsAttractor = { strength: 900, radius: 1200, falloff: 0.5, match: 'remote', repelOthers: 0.2, damping: 2 }
 *   - mode: 'spring' (with range, deadZone) pulls harder with distance and lets go near the centre.
 *   - match: only bodies whose physics.tags include this tag (or any of a list) are pulled.
 *   - repelOthers: bodies that do not match are gently pushed away (0–1).
 *   - body.physics.tagWeights: { remote: 0.6 } scales how strongly a body follows a tag.
 *
 * Fluid zone (on a rectangle; the rectangle is the water):
 *   obj.physicsFluid = { density: 1, drag: 3 }
 *   - body.physics.buoyancy: 1 is neutral, above 1 floats up, below 1 sinks.
 *
 * Orbit (on a body):
 *   body.physics.orbit = { center: 'coreId' | { x, y }, radius: 260, speed: 0.4, stiffness: 6 }
 *   - speed is in radians per second; change radius at runtime and the body glides to its new ring.
 *
 * Affinity (on the artboard; bodies attract bodies that share a tag and push away the rest):
 *   artboard.physics.affinity = { attractRadius: 900, repelRadius: 260, attract: 260, repel: 420 }
 *   - body.physics.tags: ['pricing']
 */
